package com.bank.settleops.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Finds the balance-point index where left net equals right net.
public class SettlementBalancer {
    private static final Logger log = Logger.getLogger(SettlementBalancer.class.getName());

    public int findBalancePoint(int[] settlements) {
        if (settlements == null || settlements.length == 0) {
            return -1;
        }
        long total = 0;
        for (int v : settlements) {
            total += v;
        }
        long leftSum = 0;
        for (int i = 0; i < settlements.length; i++) {
            long rightSum = total - leftSum - settlements[i];
            final int idx = i;
            final long l = leftSum, r = rightSum;
            log.fine(() -> "Index " + idx + ": left=" + l + " right=" + r);
            if (leftSum == rightSum) {
                log.info(() -> "Balance point at index " + idx + " for "
                        + Arrays.toString(settlements));
                return i;
            }
            leftSum += settlements[i];
        }
        log.info(() -> "No balance point for " + Arrays.toString(settlements));
        return -1;
    }
}
